func downloadStatusText(status string) string {
	switch status {
	case "pending":
		return "等待下载"
	case "resolving":
		return "正在解析"
	case "downloading":
		return "正在下载"
	case "tagging":
		return "正在写入标签"
	case "paused":
		return "已暂停"
	case "completed":
		return "已完成"
	case "failed":
		return "失败"
	case "cancelled":
		return "已取消"
	default:
		return status
	}
}

